<?php
namespace Database\Seeders;
use App\Enums\{CmsPageSectionType,CmsPageStatus,CmsPageType}; use App\Models\CmsPage; use Illuminate\Database\Seeder;
class CmsPageSeeder extends Seeder { public function run():void { $pages=[['about-us','About Us',CmsPageType::Standard,'A cleaner marketplace for trusted shopping.'],['help','Help & FAQ',CmsPageType::Help,'Find answers about orders, payments, shipping, and selling.'],['buyer-protection','Buyer Protection',CmsPageType::Standard,'Secure checkout, seller accountability, and clear order support.'],['seller-information','Seller Information',CmsPageType::Standard,'Learn how seller approval, products, orders, commissions, and payouts work.'],['contact','Contact',CmsPageType::Contact,'Questions about an order or selling? Contact the marketplace team.'],['privacy-policy','Privacy Policy',CmsPageType::Legal,'Demo policy content for this marketplace pitch.'],['terms-and-conditions','Terms & Conditions',CmsPageType::Legal,'Demo terms content for this marketplace pitch.'],['refund-policy','Refund Policy',CmsPageType::Legal,'Refunds are handled through the marketplace refund workflow where applicable.'],['shipping-policy','Shipping Policy',CmsPageType::Legal,'Delivery options and charges are selected per seller group at checkout.'],['seller-policy','Seller Policy',CmsPageType::Legal,'Sellers are approved, products are moderated, and fulfillment responsibilities remain with the seller.']]; foreach($pages as $i=>[$slug,$title,$type,$excerpt]){$p=CmsPage::firstOrCreate(['slug'=>$slug],['title'=>$title,'page_type'=>$type,'excerpt'=>$excerpt,'status'=>CmsPageStatus::Published,'show_in_footer'=>in_array($type,[CmsPageType::Legal,CmsPageType::Contact],true),'sort_order'=>($i+1)*10,'is_system'=>true]); if($p->sections()->exists())continue; $s=$p->sections()->create(['type'=>$slug==='help'?CmsPageSectionType::Faq:CmsPageSectionType::Text,'title'=>$title,'content'=>$slug==='help'?null:$excerpt,'sort_order'=>10]); if($slug==='help')foreach([['How do I place an order?','Add products to your cart, choose an address, shipping, and payment method, then place the order.'],['How are sellers approved?','Vendor applications are reviewed before seller operations become available.'],['How are refunds handled?','Refunds are processed through the marketplace refund workflow when eligible.']] as $j=>$f)$s->faqItems()->create(['question'=>$f[0],'answer'=>$f[1],'sort_order'=>($j+1)*10]);}} }
